{"path": "/app/parallel_linear.py", "content": """"Tensor-parallel linear layers using PyTorch distributed collectives.

ColumnParallelLinear splits the output dimension (weight rows). Each rank owns a
slice of the output features and all-gathers the local outputs.

RowParallelLinear splits the input dimension (weight columns). Each rank owns a
slice of the input features and all-reduces the partial outputs.
"""

from __future__ import annotations

import torch
import torch.nn.functional as F
from torch import nn
import torch.distributed as dist


def _distributed_available() -> bool:
    return dist.is_available() and dist.is_initialized()


def _get_world_size_rank() -> tuple[int, int]:
    if _distributed_available():
        return dist.get_world_size(), dist.get_rank()
    return 1, 0


def _get_split_sizes(total_size: int, world_size: int) -> list[int]:
    if world_size <= 1:
        return [total_size]
    base = total_size // world_size
    rem = total_size % world_size
    return [base + (1 if i < rem else 0) for i in range(world_size)]


def _split_tensor(tensor: torch.Tensor, split_sizes: list[int], dim: int) -> list[torch.Tensor]:
    if len(split_sizes) == 1:
        return [tensor]
    return list(torch.split(tensor, split_sizes, dim=dim))


class _AllGather(torch.autograd.Function):
    @staticmethod
    def forward(ctx, input: torch.Tensor, dim: int, split_sizes: list[int] | None):
        world_size, _ = _get_world_size_rank()
        ctx.world_size = world_size
        ctx.dim = dim
        ctx.split_sizes = split_sizes
        if world_size == 1:
            return input
        if split_sizes is None:
            tensor_list = [torch.empty_like(input) for _ in range(world_size)]
            dist.all_gather(tensor_list, input)
            return torch.cat(tensor_list, dim=dim)
        max_size = max(split_sizes)
        if input.size(dim) < max_size:
            pad_shape = list(input.shape)
            pad_shape[dim] = max_size - input.size(dim)
            padding = torch.zeros(pad_shape, device=input.device, dtype=input.dtype)
            input_padded = torch.cat([input, padding], dim=dim)
        else:
            input_padded = input
        tensor_list = [torch.empty_like(input_padded) for _ in range(world_size)]
        dist.all_gather(tensor_list, input_padded)
        outputs = [tensor.narrow(dim, 0, size) for tensor, size in zip(tensor_list, split_sizes)]
        return torch.cat(outputs, dim=dim)

    @staticmethod
    def backward(ctx, grad_output: torch.Tensor):
        world_size = ctx.world_size
        dim = ctx.dim
        split_sizes = ctx.split_sizes
        if world_size == 1:
            return grad_output, None, None
        rank = _get_world_size_rank()[1]
        if split_sizes is None:
            dim_size = grad_output.size(dim)
            chunk_size = dim_size // world_size
            grad_chunks = torch.split(grad_output, chunk_size, dim=dim)
            return grad_chunks[rank].contiguous(), None, None
        grad_chunks = torch.split(grad_output, split_sizes, dim=dim)
        return grad_chunks[rank].contiguous(), None, None


def _all_gather_along_dim(tensor: torch.Tensor, dim: int, split_sizes: list[int] | None) -> torch.Tensor:
    return _AllGather.apply(tensor, dim, split_sizes)


class _Scatter(torch.autograd.Function):
    @staticmethod
    def forward(ctx, input: torch.Tensor, dim: int, split_sizes: list[int] | None):
        world_size, rank = _get_world_size_rank()
        ctx.world_size = world_size
        ctx.dim = dim
        ctx.split_sizes = split_sizes
        if world_size == 1:
            return input
        if split_sizes is None:
            dim_size = input.size(dim)
            chunk_size = dim_size // world_size
            chunks = torch.split(input, chunk_size, dim=dim)
        else:
            chunks = torch.split(input, split_sizes, dim=dim)
        return chunks[rank].contiguous()

    @staticmethod
    def backward(ctx, grad_output: torch.Tensor):
        world_size = ctx.world_size
        dim = ctx.dim
        split_sizes = ctx.split_sizes
        if world_size == 1:
            return grad_output, None, None
        if split_sizes is None:
            tensor_list = [torch.empty_like(grad_output) for _ in range(world_size)]
            dist.all_gather(tensor_list, grad_output)
            return torch.cat(tensor_list, dim=dim), None, None
        max_size = max(split_sizes)
        if grad_output.size(dim) < max_size:
            pad_shape = list(grad_output.shape)
            pad_shape[dim] = max_size - grad_output.size(dim)
            padding = torch.zeros(pad_shape, device=grad_output.device, dtype=grad_output.dtype)
            grad_padded = torch.cat([grad_output, padding], dim=dim)
        else:
            grad_padded = grad_output
        tensor_list = [torch.empty_like(grad_padded) for _ in range(world_size)]
        dist.all_gather(tensor_list, grad_padded)
        grads = [tensor.narrow(dim, 0, size) for tensor, size in zip(tensor_list, split_sizes)]
        return torch.cat(grads, dim=dim), None, None


def _scatter_along_dim(tensor: torch.Tensor, dim: int, split_sizes: list[int] | None) -> torch.Tensor:
    return _Scatter.apply(tensor, dim, split_sizes)


class _AllReduce(torch.autograd.Function):
    @staticmethod
    def forward(ctx, input: torch.Tensor):
        world_size, _ = _get_world_size_rank()
        if world_size == 1:
            return input
        output = input.clone()
        dist.all_reduce(output)
        return output

    @staticmethod
    def backward(ctx, grad_output: torch.Tensor):
        return grad_output


def _all_reduce(tensor: torch.Tensor) -> torch.Tensor:
    return _AllReduce.apply(tensor)


class ColumnParallelLinear(nn.Module):
    def __init__(self, in_features: int, out_features: int, bias: bool = True, master_weight: torch.Tensor | None = None):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features
        world_size, rank = _get_world_size_rank()
        self.world_size = world_size
        self.rank = rank
        self.output_split_sizes = _get_split_sizes(out_features, world_size)
        if master_weight is None:
            master_weight = torch.empty(out_features, in_features)
            nn.init.xavier_uniform_(master_weight)
        if master_weight.shape != (out_features, in_features):
            raise ValueError("master_weight shape must be (out_features, in_features)")
        weight_parts = _split_tensor(master_weight, self.output_split_sizes, dim=0)
        local_weight = weight_parts[rank].contiguous()
        self.weight = nn.Parameter(local_weight.clone().detach())
        if bias:
            bias_tensor = torch.zeros(self.output_split_sizes[rank], device=local_weight.device, dtype=local_weight.dtype)
            self.bias = nn.Parameter(bias_tensor)
        else:
            self.register_parameter("bias", None)

    def forward(self, input: torch.Tensor) -> torch.Tensor:
        output_parallel = F.linear(input, self.weight, self.bias)
        if self.world_size == 1:
            return output_parallel
        return _all_gather_along_dim(output_parallel, dim=-1, split_sizes=self.output_split_sizes)


class RowParallelLinear(nn.Module):
    def __init__(self, in_features: int, out_features: int, bias: bool = True, master_weight: torch.Tensor | None = None):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features
        world_size, rank = _get_world_size_rank()
        self.world_size = world_size
        self.rank = rank
        self.input_split_sizes = _get_split_sizes(in_features, world_size)
        if master_weight is None:
            master_weight = torch.empty(out_features, in_features)
            nn.init.xavier_uniform_(master_weight)
        if master_weight.shape != (out_features, in_features):
            raise ValueError("master_weight shape must be (out_features, in_features)")
        weight_parts = _split_tensor(master_weight, self.input_split_sizes, dim=1)
        local_weight = weight_parts[rank].contiguous()
        self.weight = nn.Parameter(local_weight.clone().detach())
        if bias:
            bias_tensor = torch.zeros(out_features, device=local_weight.device, dtype=local_weight.dtype)
            self.bias = nn.Parameter(bias_tensor)
        else:
            self.register_parameter("bias", None)

    def forward(self, input: torch.Tensor) -> torch.Tensor:
        if self.world_size == 1:
            return F.linear(input, self.weight, self.bias)
        input_parallel = _scatter_along_dim(input, dim=-1, split_sizes=self.input_split_sizes)
        output_parallel = F.linear(input_parallel, self.weight, None)
        output = _all_reduce(output_parallel)
        if self.bias is not None:
            output = output + self.bias
        return output


__all__ = ["ColumnParallelLinear", "RowParallelLinear"]
